        cards: cards.map(c => ({
          id: c.id,
          column_id: c.column_id,
          text: c.text,
          position: c.position,
          created_at: c.created_at
        }))
      });
    }

    res.json(board);
  } catch (err) {
    console.error('Error fetching board:', err);
    res.status(500).json({ error: 'Failed to fetch board state' });
  }
});

export { router as boardRouter };
