    const card = updated[0];

    // Check for precision issues and renormalize if needed
    await maybeRenormalizeColumn(db, column_id);

    // Broadcast the move to all connected clients
    broadcastEvent({
      type: 'move',
      card: {
        id: card.id,
        column_id: card.column_id,
        text: card.text,
        position: card.position,
        created_at: card.created_at
      }
    });

    res.json(card);
  } catch (err) {
    console.error('Error moving card:', err);
    res.status(500).json({ error: 'Failed to move card' });
  }
});

/**
 * DELETE /api/cards/:id - Delete a card
 */
router.delete('/:id', async (req, res) => {
  try {
    const db = getDb();
    const { id } = req.params;

    // Verify card exists
    const { rows: existingCards } = await db.query(
      'SELECT id FROM cards WHERE id = $1',
      [id]
    );
    if (existingCards.length === 0) {
      return res.status(404).json({ error: 'Card not found' });
    }

    await db.query('DELETE FROM cards WHERE id = $1', [id]);

    broadcastEvent({
      type: 'delete',
      card_id: id
    });

    res.status(204).send();
  } catch (err) {
    console.error('Error deleting card:', err);
    res.status(500).json({ error: 'Failed to delete card' });
  }
});

export { router as cardsRouter };
", "path": "server/routes/cards.js"}

{"content": "import { Router } from 'express';

const router = Router();

// Store active SSE connections
let clients = new Set();

/**
 * Broadcast an event to all connected SSE clients
 */
export function broadcastEvent(data) {
  const message = `data: ${JSON.stringify(data)}\n\n`;
  for (const client of clients) {
    try {
      client.write(message);
    } catch (err) {
      console.error('Error broadcasting to client:', err);
    }
  }
}

/**
 * GET /api/stream - SSE endpoint for real-time updates
 */
router.get('/', (req, res) => {
  // Set SSE headers
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no');

  // Send initial comment to keep connection alive
  res.write(': connected\n\n');

  clients.add(res);

  // Handle client disconnect
  req.on('close', () => {
    clients.delete(res);
  });

  // Handle errors
  res.on('error', () => {
    clients.delete(res);
  });
});

export { router as streamRouter };
", "path": "server/routes/stream.js"}

