}

/**
 * Handle a card deletion event.
 */
function handleDeleteEvent(cardId) {
  for (const col of boardState) {
    const idx = col.cards.findIndex(c => c.id === cardId);
    if (idx >= 0) {
      col.cards.splice(idx, 1);
