function reconcileCard(canonicalCard) {
  // Remove card from its current position in state
  for (const col of boardState) {
    const idx = col.cards.findIndex(c => c.id === canonicalCard.id);
    if (idx >= 0) {
      col.cards.splice(idx, 1);
