  const { rows: normalizedCards } = await db.query(
    'SELECT id, column_id, text, position, created_at FROM cards WHERE column_id = $1 ORDER BY position',
    [columnId]
  );

  broadcastEvent({
    type: 'renormalize',
    column_id: columnId,
    cards: normalizedCards.map(c => ({
      id: c.id,
      column_id: c.column_id,
      text: c.text,
