 */
function insertCardAtPosition(column, card) {
  let inserted = false;
  for (let i = 0; i < column.cards.length; i++) {
    if (column.cards[i].position > card.position) {
      column.cards.splice(i, 0, { ...card });
      inserted = true;
      break;
    }
  }
  if (!inserted) {
    column.cards.push({ ...card });
  }
}

