/**
 * Handle a card move event from the server.
 */
function handleMoveEvent(card) {
  const existing = findCard(card.id);

  if (!existing) {
    // Shouldn't happen, but add it anyway
    const col = findColumn(card.column_id);
    if (col) {
      insertCardAtPosition(col, card);
